"""Single-thread coroutine driver for an offline event tape; no sockets.

Ordering inside one virtual millisecond is fixed by ``kind``:

``-1`` initial case starts, ``0`` external events (input order), ``1`` pause
completions (case order), ``2`` response timeouts (case order).  ``order`` and
the monotonic ``sequence`` break the remaining ties, which reproduces the
documented same-time interleaving without any real sleeping.
"""
import heapq

MAX_TIME = (1 << 63) - 1

START = -1
EXTERNAL = 0
PAUSE = 1
TIMEOUT = 2


class Future:
    def __init__(self):
        self.value = None
        self.error = None
        self.finished = False
        self.listeners = []

    def done(self):
        return self.finished

    def set_result(self, value):
        if self.finished:
            return
        self.finished = True
        self.value = value
        listeners, self.listeners = self.listeners, []
        for callback in listeners:
            callback(self)

    def set_exception(self, error):
        if self.finished:
            return
        self.error = error
        self.set_result(None)

    def __await__(self):
        if not self.finished:
            yield self
        if self.error is not None:
            raise self.error
        return self.value


class Task(Future):
    def __init__(self, clock, coroutine):
        Future.__init__(self)
        self.clock = clock
        self.coroutine = coroutine

    def step(self, previous=None):
        if self.finished:
            return
        try:
            if previous is None:
                wait = self.coroutine.send(None)
            elif previous.error is not None:
                wait = self.coroutine.throw(previous.error)
            else:
                wait = self.coroutine.send(previous.value)
        except StopIteration as stop:
            self.set_result(stop.value)
            return
        except BaseException as exc:          # noqa: BLE001 - reported below
            self.set_exception(exc)
            return
        if not isinstance(wait, Future):
            self.set_exception(TypeError('unsupported awaitable'))
            return
        wait.listeners.append(self.step)


class Clock:
    def __init__(self):
        self.now = 0
        self.events = []
        self.sequence = 0

    def create_future(self):
        return Future()

    def schedule(self, time, kind, order, callback):
        if not self.now <= time <= MAX_TIME:
            raise ValueError('clock range')
        self.sequence += 1
        heapq.heappush(self.events, (time, kind, order, self.sequence, callback))

    def sleep(self, duration, order):
        future = Future()
        self.schedule(self.now + duration, PAUSE, order,
                      lambda: future.set_result(None))
        return future

    def run(self, coroutines, records, dispatch):
        tasks = [Task(self, coroutine) for coroutine in coroutines]
        for index, task in enumerate(tasks):
            self.schedule(0, START, index, task.step)
        for index, record in enumerate(records):
            self.schedule(record.at, EXTERNAL, index,
                          lambda record=record: dispatch(record))
        while self.events:
            time, _, _, _, callback = heapq.heappop(self.events)
            self.now = time
            callback()
        for task in tasks:
            if not task.done():
                raise RuntimeError('unfinished offline task')
            if task.error is not None:
                raise task.error
        return [task.value for task in tasks]
