"""HttpClient request/event core with an injected offline transport and clock."""
from modules.events import (ConnectionTerminated, DataReceived,
                            HeadersReceived, SendError)


class CaseStream:
    """Per-case replay bookkeeping kept by the client."""
    __slots__ = ('index', 'stream', 'events', 'end_retained', 'send_done',
                 'sent_ended', 'waiter', 'pause', 'terminal')

    def __init__(self, index, stream):
        self.index = index
        self.stream = stream
        self.events = []
        self.end_retained = False
        self.send_done = False
        self.sent_ended = False
        self.waiter = None
        self.pause = None
        self.terminal = False


class HttpClient:
    def __init__(self, clock, backend, timeout_ms):
        self._loop = clock
        self._http = backend
        self._quic = backend
        self._timeout_ms = timeout_ms
        self._streams = {}
        self._closed = False
        self._close_reason = None

    def _log(self, msg):
        pass

    # -- request side -----------------------------------------------------
    async def request(self, case, case_index):
        stream_id = self._quic.get_next_available_stream_id()
        state = CaseStream(case_index, stream_id)
        self._streams[stream_id] = state
        outcome = 'ok'
        try:
            for item in case:
                if self._closed:
                    raise ConnectionError(self._close_reason)
                kind = item.Type
                if kind == 'sleep':
                    # A pause emits nothing, cannot finish the request and is
                    # still allowed after the send side ended.
                    pause = self._loop.sleep(item.Time_to_Stop, case_index)
                    state.pause = pause
                    try:
                        await pause
                    finally:
                        state.pause = None
                    continue
                if state.sent_ended:
                    raise SendError('frame after request end')
                if kind == 'headers':
                    self._http.send_headers(stream_id=stream_id,
                                            headers=item.data_to_transfered,
                                            end_stream=item.End_Stream)
                elif kind == 'data':
                    self._http.send_data(stream_id=stream_id,
                                         data=item.data_to_transfered,
                                         end_stream=item.End_Stream)
                elif kind == 'datagram':
                    # Datagram End_Stream is ignored by the recording.
                    self._http.send_datagram(stream_id=stream_id,
                                             data=item.data_to_transfered)
                else:
                    raise SendError('unknown frame type')
                self.transmit()
                if kind in ('headers', 'data') and item.End_Stream:
                    state.sent_ended = True
            state.send_done = True
            if state.end_retained:
                outcome = 'ok'
            else:
                waiter = self._loop.create_future()
                state.waiter = waiter
                self._loop.schedule(self._loop.now + self._timeout_ms, 2,
                                    case_index, lambda: self._expire(state))
                await waiter
                outcome = 'ok'
        except ConnectionError:
            outcome = 'closed'
        except TimeoutError:
            outcome = 'timeout'
        except SendError:
            outcome = 'send_error'
        finally:
            state.terminal = True
            state.pause = None
        return {'state': outcome, 'at': self._loop.now, 'events': state.events,
                'stream': stream_id, 'index': case_index}

    def transmit(self):
        return None

    def _expire(self, state):
        waiter = state.waiter
        if waiter is not None and not waiter.done():
            waiter.set_exception(TimeoutError('Time Out'))

    # -- response side ----------------------------------------------------
    def http_event_received(self, event):
        state = self._streams.get(event.stream_id)
        if state is None or state.terminal or state.end_retained:
            # Unknown stream, already terminal case, or a later response event.
            return
        state.events.append((self._loop.now, event))
        if event.stream_ended:
            state.end_retained = True
            waiter = state.waiter
            if state.send_done and waiter is not None and not waiter.done():
                waiter.set_result(None)

    def quic_event_received(self, event):
        if isinstance(event, ConnectionTerminated):
            if self._closed:
                return
            self._closed = True
            self._close_reason = event.reason_phrase
            for state in list(self._streams.values()):
                if state.terminal:
                    continue
                pending = state.pause if state.pause is not None else state.waiter
                if pending is not None and not pending.done():
                    pending.set_exception(ConnectionError(self._close_reason))
            return
        self.http_event_received(event)

    def connection_lost(self, exc=None):
        self.quic_event_received(ConnectionTerminated(reason_phrase='Connection lost'))
